Method.Implementation:
 #DIM status AS %Status
 set status = $$$OK	 

try {	
 	if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("CdrHl7AddressUpdateOperation", "CdrHl7AddressUpdateOperation failed. ; Reason: " _ result)						
			return status
		}
 	}
			$$$TRACE(" Calling MMIAddress: " _pRequest.RawContent) 				 				 	
	 		set pResponse=##class(Ens.StringResponse).%New()

	 			$$$TRACE("Call addressUpdateMMI")	 		
	 			Set pResponse.StringValue = ..objCdrTuxService.addressUpdateMMI(pRequest.RawContent)
	 			Set respData = pResponse.StringValue	
	 			set respData = "1"	 		
	 			$$$TRACE(" Call after the Address Update .."_respData)		 				 		

 }	 
 catch err {	
	    Set status = ..ExceptionHandler(err, "OnMessage")
 }	 
return status
